CREATE TABLE IF NOT EXISTS gis_phase378_resource_candidates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_key TEXT NOT NULL,resource_url TEXT NOT NULL,resource_type TEXT NOT NULL,discovery_method TEXT NOT NULL,source_page TEXT,confidence DOUBLE PRECISION NOT NULL DEFAULT 0,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(dataset_key,resource_url));